commands.command:
import kip

values = kip.prompt([
    {'name': 'env', 'type': 'select', 'label': 'Environment', 'options': ['dev', 'staging', 'prod'], 'required': True},
    {'name': 'dry', 'type': 'flags', 'label': 'Options', 'options': [{'name': 'dry', 'label': 'Dry run'}]},
], id='where', title='Where to?')

if values['env'] == 'prod' and not kip.confirm('Deploy to production?', danger=True, confirm_label='Deploy'):
    kip.done(title='Cancelled', level='warning')
else:
    kip.progress(50, 'Deploying...')
    kip.done(title='Deployed to ' + values['env'], text='dry run' if values['dry']['dry'] else None)

const values = await kip.prompt([
  { name: 'env', type: 'select', label: 'Environment', options: ['dev', 'staging', 'prod'], required: true },
], { id: 'where', title: 'Where to?' });

kip.progress(50, 'Deploying...');
kip.done({ title: 'Deployed to ' + values.env });
